--
-- Table categories
--
DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` varchar(48) NOT NULL,
  `name_en` varchar(80) NOT NULL,
  `name_id` varchar(80) NOT NULL,
  `icon` varchar(48) NOT NULL,
  `color` char(7) NOT NULL DEFAULT '#857B70',
  `sort_order` smallint(6) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `categories` (`id`,`name_en`,`name_id`,`icon`,`color`,`sort_order`,`is_active`) VALUES ('beauty-health','Beauty & Health','Kecantikan & Kesehatan','sparkles','#C2417A','3','1'),('department-store','Department Store & Supermarket','Department Store & Supermarket','shopping-cart','#2F9E44','7','1'),('electronics','Gadgets & Electronics','Gadget & Elektronik','smartphone','#0B8A8A','4','1'),('entertainment','Entertainment','Hiburan','clapperboard','#7B4FD6','6','1'),('fashion','Fashion & Lifestyle','Fashion & Gaya Hidup','shirt','#3B5BDB','2','1'),('food-beverage','Food & Beverage','Makanan & Minuman','utensils','#D9822B','1','1'),('kids-family','Kids & Family','Anak & Keluarga','baby','#E0A800','5','1'),('services','Hotel, Travel & Services','Hotel, Travel & Layanan','concierge-bell','#6B7280','8','1');

--
-- Table closures
--
DROP TABLE IF EXISTS `closures`;
CREATE TABLE `closures` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `leg_id` int(10) unsigned DEFAULT NULL,
  `bank_id` varchar(48) DEFAULT NULL,
  `edge_id` int(10) unsigned DEFAULT NULL,
  `amenity_id` varchar(64) DEFAULT NULL,
  `direction` enum('both','up','down') NOT NULL DEFAULT 'both',
  `starts_at` datetime NOT NULL,
  `ends_at` datetime DEFAULT NULL,
  `reason_en` varchar(160) DEFAULT NULL,
  `reason_id` varchar(160) DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `ended_by` int(10) unsigned DEFAULT NULL,
  `ended_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cl_active` (`ends_at`,`starts_at`),
  KEY `fk_cl_leg` (`leg_id`),
  KEY `fk_cl_bank` (`bank_id`),
  KEY `fk_cl_edge` (`edge_id`),
  KEY `fk_cl_am` (`amenity_id`),
  KEY `fk_cl_user` (`created_by`),
  KEY `fk_cl_user2` (`ended_by`),
  CONSTRAINT `fk_cl_am` FOREIGN KEY (`amenity_id`) REFERENCES `amenities` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cl_bank` FOREIGN KEY (`bank_id`) REFERENCES `connector_banks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cl_edge` FOREIGN KEY (`edge_id`) REFERENCES `graph_edges` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cl_leg` FOREIGN KEY (`leg_id`) REFERENCES `connector_legs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cl_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cl_user2` FOREIGN KEY (`ended_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_cl_target` CHECK ((`leg_id` is not null) + (`bank_id` is not null) + (`edge_id` is not null) + (`amenity_id` is not null) = 1)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
