--
-- Table floors
--
DROP TABLE IF EXISTS `floors`;
CREATE TABLE `floors` (
  `id` varchar(32) NOT NULL,
  `level` tinyint(4) NOT NULL,
  `short` varchar(8) NOT NULL,
  `name_en` varchar(80) NOT NULL,
  `name_id` varchar(80) NOT NULL,
  `building` enum('pentacity','ewalk','both') NOT NULL,
