--
-- Table i18n_strings
--
DROP TABLE IF EXISTS `i18n_strings`;
CREATE TABLE `i18n_strings` (
  `key` varchar(64) NOT NULL,
  `en` varchar(500) DEFAULT NULL,
  `id` varchar(500) DEFAULT NULL,
  `note` varchar(160) DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`key`),
  KEY `fk_i18n_user` (`updated_by`),
  CONSTRAINT `fk_i18n_user` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Table kiosks
--
DROP TABLE IF EXISTS `kiosks`;
CREATE TABLE `kiosks` (
  `id` varchar(48) NOT NULL,
  `name` varchar(80) NOT NULL,
  `floor_id` varchar(32) NOT NULL,
  `building` enum('pentacity','ewalk') NOT NULL,
  `x` decimal(10,2) NOT NULL,
  `y` decimal(10,2) NOT NULL,
  `node_id` int(10) unsigned DEFAULT NULL,
  `facing_deg` smallint(6) DEFAULT NULL,
  `default_lang` enum('en','id') NOT NULL DEFAULT 'en',
  `attract_lang` enum('en','id') NOT NULL DEFAULT 'en',
  `client_type` enum('windows_pc','smart_tv','android_box','other') NOT NULL DEFAULT 'windows_pc',
  `perf_mode` enum('auto','full','lite') NOT NULL DEFAULT 'auto',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `token_hash` char(64) DEFAULT NULL,
  `token_hint` char(4) DEFAULT NULL,
  `hw_note` varchar(255) DEFAULT NULL,
  `src_id` varchar(64) DEFAULT NULL,
  `last_seen_at` datetime DEFAULT NULL,
  `ip_last` varchar(45) DEFAULT NULL,
  `app_build` varchar(32) DEFAULT NULL,
  `data_version` varchar(32) DEFAULT NULL,
  `promos_version` varchar(32) DEFAULT NULL,
  `status_version` varchar(32) DEFAULT NULL,
  `user_agent` varchar(400) DEFAULT NULL,
  `perf_active` enum('full','lite') DEFAULT NULL,
  `perf_reason` varchar(120) DEFAULT NULL,
  `sw_active` tinyint(1) DEFAULT NULL,
  `screen` varchar(40) DEFAULT NULL,
  `uptime_sec` int(10) unsigned DEFAULT NULL,
  `last_error` varchar(500) DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_kiosk_seen` (`last_seen_at`),
  KEY `fk_kiosk_floor` (`floor_id`),
  KEY `fk_kiosk_node` (`node_id`),
  KEY `fk_kiosk_user` (`updated_by`),
  CONSTRAINT `fk_kiosk_floor` FOREIGN KEY (`floor_id`) REFERENCES `floors` (`id`),
  CONSTRAINT `fk_kiosk_node` FOREIGN KEY (`node_id`) REFERENCES `graph_nodes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_kiosk_user` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
