--
-- Table login_attempts
--
DROP TABLE IF EXISTS `login_attempts`;
CREATE TABLE `login_attempts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(190) DEFAULT NULL,
  `ip` varchar(45) NOT NULL,
  `success` tinyint(1) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_ip_time` (`ip`,`created_at`),
  KEY `idx_email_time` (`email`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=162 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Table media
--
DROP TABLE IF EXISTS `media`;
CREATE TABLE `media` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `kind` enum('logo','image','video','svg','other') NOT NULL,
  `path` varchar(255) NOT NULL,
  `path_2x` varchar(255) DEFAULT NULL,
  `mime` varchar(64) NOT NULL,
  `bytes` int(10) unsigned NOT NULL,
  `width` smallint(5) unsigned DEFAULT NULL,
  `height` smallint(5) unsigned DEFAULT NULL,
  `duration_sec` decimal(6,2) DEFAULT NULL,
  `sha256` char(64) NOT NULL,
  `original_name` varchar(190) DEFAULT NULL,
  `alt_text` varchar(190) DEFAULT NULL,
  `meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`meta`)),
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_media_sha_kind` (`sha256`,`kind`),
  KEY `idx_media_kind` (`kind`),
  KEY `fk_media_user` (`created_by`),
  CONSTRAINT `fk_media_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=229 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
