--
-- Table promos
--
DROP TABLE IF EXISTS `promos`;
CREATE TABLE `promos` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `title_en` varchar(120) NOT NULL,
  `title_id` varchar(120) NOT NULL,
  `sub_en` varchar(200) DEFAULT NULL,
  `sub_id` varchar(200) DEFAULT NULL,
  `kind` enum('text','image','video') NOT NULL DEFAULT 'image',
  `media_id` int(10) unsigned DEFAULT NULL,
  `poster_media_id` int(10) unsigned DEFAULT NULL,
  `bg_color` char(7) DEFAULT NULL,
  `slot` enum('attract-hero','attract-fullscreen','panel-banner','phone-arrival') NOT NULL DEFAULT 'attract-hero',
  `link_type` enum('none','tenant','category','event','url') NOT NULL DEFAULT 'none',
  `link_ref` varchar(500) DEFAULT NULL,
  `starts_at` datetime NOT NULL,
  `ends_at` datetime NOT NULL,
  `days_mask` tinyint(3) unsigned NOT NULL DEFAULT 127,
  `time_from` time DEFAULT NULL,
  `time_to` time DEFAULT NULL,
  `duration_sec` tinyint(3) unsigned NOT NULL DEFAULT 8,
  `weight` tinyint(3) unsigned NOT NULL DEFAULT 5,
  `status` enum('draft','active','paused','archived') NOT NULL DEFAULT 'draft',
  `all_kiosks` tinyint(1) NOT NULL DEFAULT 1,
  `advertiser_tenant_id` varchar(64) DEFAULT NULL,
  `advertiser_name` varchar(120) DEFAULT NULL,
  `max_impressions` int(10) unsigned DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_promo_window` (`status`,`starts_at`,`ends_at`),
  KEY `fk_promo_media` (`media_id`),
  KEY `fk_promo_poster` (`poster_media_id`),
  KEY `fk_promo_adv` (`advertiser_tenant_id`),
  KEY `fk_promo_cb` (`created_by`),
  KEY `fk_promo_ub` (`updated_by`),
  CONSTRAINT `fk_promo_adv` FOREIGN KEY (`advertiser_tenant_id`) REFERENCES `tenants` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_promo_cb` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_promo_media` FOREIGN KEY (`media_id`) REFERENCES `media` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_promo_poster` FOREIGN KEY (`poster_media_id`) REFERENCES `media` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_promo_ub` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_promo_weight` CHECK (`weight` between 1 and 10)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Table promo_targets
--
DROP TABLE IF EXISTS `promo_targets`;
CREATE TABLE `promo_targets` (
  `promo_id` int(10) unsigned NOT NULL,
  `kiosk_id` varchar(48) NOT NULL,
  PRIMARY KEY (`promo_id`,`kiosk_id`),
  KEY `fk_pt_kiosk` (`kiosk_id`),
  CONSTRAINT `fk_pt_kiosk` FOREIGN KEY (`kiosk_id`) REFERENCES `kiosks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pt_promo` FOREIGN KEY (`promo_id`) REFERENCES `promos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Table rate_limits
--
DROP TABLE IF EXISTS `rate_limits`;
CREATE TABLE `rate_limits` (
  `bucket` varchar(120) NOT NULL,
  `window_start` int(10) unsigned NOT NULL,
  `hits` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`bucket`,`window_start`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Table releases
--
DROP TABLE IF EXISTS `releases`;
CREATE TABLE `releases` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `channel` enum('directory','promos','status') NOT NULL,
  `version` varchar(32) NOT NULL,
  `seq` int(10) unsigned NOT NULL,
  `sha256` char(64) NOT NULL,
  `bytes` int(10) unsigned NOT NULL,
  `path` varchar(255) NOT NULL,
  `revs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`revs`)),
  `stats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`stats`)),
  `diff` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`diff`)),
  `validation` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`validation`)),
  `notes` varchar(500) DEFAULT NULL,
  `is_live` tinyint(1) NOT NULL DEFAULT 0,
  `rolled_back_from` int(10) unsigned DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rel` (`channel`,`version`),
  UNIQUE KEY `uq_rel_seq` (`channel`,`seq`),
  KEY `idx_rel_live` (`channel`,`is_live`),
  KEY `fk_rel_rb` (`rolled_back_from`),
  KEY `fk_rel_user` (`created_by`),
