--
-- Table tenant_hours
--
DROP TABLE IF EXISTS `tenant_hours`;
CREATE TABLE `tenant_hours` (
  `tenant_id` varchar(64) NOT NULL,
  `dow` tinyint(3) unsigned NOT NULL,
  `open_time` time DEFAULT NULL,
  `close_time` time DEFAULT NULL,
  `is_closed` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`tenant_id`,`dow`),
  CONSTRAINT `fk_th_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_th_dow` CHECK (`dow` between 1 and 7)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Table users
--
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(190) NOT NULL,
  `name` varchar(120) NOT NULL,
  `role` enum('superadmin','map_editor','leasing','marketing','operations','security','viewer') NOT NULL DEFAULT 'viewer',
  `password_hash` varchar(255) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `must_change_password` tinyint(1) NOT NULL DEFAULT 1,
  `failed_count` smallint(5) unsigned NOT NULL DEFAULT 0,
  `locked_until` datetime DEFAULT NULL,
  `last_login_at` datetime DEFAULT NULL,
  `password_changed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `users` (`id`,`email`,`name`,`role`,`password_hash`,`is_active`,`must_change_password`,`failed_count`,`locked_until`,`last_login_at`,`password_changed_at`,`created_at`,`updated_at`) VALUES ('1','admin@bsb.local','Admin IT WBL','superadmin','$argon2id$v=19$m=65536,t=4,p=1$SGltaDNQNTM3L21SQ28uMg$UCiAkeLucle/VdRoF7ERAAK1KyYD5Qe3kDJ6ApGT5pw','1','0','0',NULL,'2026-10-27 15:47:14','2026-10-21 11:06:31','2026-10-04 03:58:07','2026-10-27 15:47:14');

--
-- Table validation_runs
--
DROP TABLE IF EXISTS `validation_runs`;
CREATE TABLE `validation_runs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ok` tinyint(1) NOT NULL,
  `errors` smallint(5) unsigned NOT NULL,
  `warnings` smallint(5) unsigned NOT NULL,
  `report` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`report`)),
  `revs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`revs`)),
  `ms` int(10) unsigned DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_vr_user` (`created_by`),
